const cmd = `
$base = 'D:\\Users\\jjq21\\AppData\\Local\\Programs\\DeepSeek Harness\\resources'
Get-ChildItem $base | Select-Object Name,Length | Format-Table -AutoSize | Out-String
Write-Output '--- top of app.asar\\dsh ---'
try { Get-ChildItem (Join-Path $base 'app.asar\\dsh') | Select-Object -First 30 Name | Format-Table -AutoSize | Out-String } catch { 'ERR ' + $_.Exception.Message }
`;
const r = await tools.pwsh({ description: "List DSH resources directory", command: cmd, timeoutMs: 60000 });
if (r.kind === "foreground") console.log(r.stdout.text.slice(0, 3000), r.stderr.text.slice(0, 500));
